from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the centered, solid separator.
    sep = None
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)) and c == w - c - 1:
            sep = ("v", c)
            break
    if sep is None:
        for r in range(h):
            if all(v == grid[r][0] for v in grid[r]) and r == h - r - 1:
                sep = ("h", r)
                break

    if sep is None:
        return [row[:] for row in grid]

    direction, i = sep
    if direction == "v":
        left = [row[:i] for row in grid]
        right = [row[i + 1:] for row in grid]
    else:
        left = [row[:] for row in grid[:i]]
        right = [row[:] for row in grid[i + 1:]]

    def dominant(panel):
        return Counter(v for row in panel for v in row).most_common(1)[0][0]

    bg1, bg2 = dominant(left), dominant(right)

    def foreground(panel, bg):
        counts = Counter(v for row in panel for v in row if v != bg)
        return counts.most_common(1)[0][0] if counts else bg

    fg1, fg2 = foreground(left, bg1), foreground(right, bg2)
    out = []

    for r in range(len(left)):
        row = []
        for c in range(len(left[0])):
            a, b = left[r][c], right[r][c]
            if fg1 == fg2:
                row.append(3 if a == fg1 and b == fg2 else fg1)
            else:
                row.append((bg1 if bg1 == bg2 else bg1)
                           if (a != bg1 or b != bg2) else 3)
        out.append(row)

    return out
